import{_ as t,o,c as r,a4 as s}from"./chunks/framework.bruR1JhL.js";const i="/tilepress/screenshots/history.webp",f=JSON.parse('{"title":"History","description":"The list of files your tools have made, where they came from and when, and how to search, clear or turn it off.","frontmatter":{"title":"History","description":"The list of files your tools have made, where they came from and when, and how to search, clear or turn it off."},"headers":[],"relativePath":"docs/history.md","filePath":"docs/history.md","lastUpdated":1795509372000}'),a={name:"docs/history.md"};function n(h,e,l,d,c,g){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h1><p>Tilepress keeps a list of the files its tools make. Use it to find a file you saved last week, to see which file it was made from, or to check why a run failed. The history stays on your PC.</p><p><img src="'+i+'" alt="The History panel open over Merge PDF, listing recent runs with their files"></p><p>Click the <strong>History</strong> button (the clock) in the top bar to open it. Press <kbd>Esc</kbd> or click elsewhere to close it.</p><h2 id="what-is-recorded" tabindex="-1">What is recorded <a class="header-anchor" href="#what-is-recorded" aria-label="Permalink to &quot;What is recorded&quot;">​</a></h2><p>Each time a tool saves something, or tries to and fails, one entry is added with:</p><ul><li>the tool&#39;s name, such as <strong>Merge PDF</strong> or <strong>Compress Image</strong>;</li><li>when it started and how long it took;</li><li>the files it started from (their paths);</li><li>the files it wrote (their paths and sizes);</li><li>for a failed run, the error message.</li></ul><p>A few tools are listed under a more specific name:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Listed as</th></tr></thead><tbody><tr><td>PDF Forms</td><td><strong>Fill PDF form</strong> or <strong>Add PDF form fields</strong></td></tr><tr><td>Protect PDF</td><td><strong>Protect PDF</strong>, or <strong>Unlock PDF</strong> when you remove a password</td></tr><tr><td>Sign PDF</td><td><strong>Sign PDF</strong> for a digital signature, <strong>Create certificate</strong> for a new certificate. A handwritten (electronic) signature is listed as <strong>Edit PDF</strong>.</td></tr><tr><td>Advanced Print</td><td><strong>Print</strong>, or <strong>Print to PDF</strong> for <strong>Save layout as PDF</strong></td></tr><tr><td>PDF to JPG</td><td><strong>PDF to JPG</strong> or <strong>PDF to PNG</strong>, by the format you chose</td></tr></tbody></table><p>For HTML to PDF and HTML to Image, the source is the web address or the HTML file you gave.</p><h2 id="what-is-never-recorded" tabindex="-1">What is never recorded <a class="header-anchor" href="#what-is-never-recorded" aria-label="Permalink to &quot;What is never recorded&quot;">​</a></h2><ul><li><strong>Tool options.</strong> The settings you chose aren&#39;t stored. That includes every password you type into Protect PDF, Unlock or Sign PDF, so they never reach the disk.</li><li><strong>What you type.</strong> Text for Edit PDF, watermarks or page numbers, pasted HTML code and typed Markdown aren&#39;t stored.</li><li><strong>The contents of your files.</strong> Only paths, sizes, times and error messages are kept.</li><li><strong>Things that don&#39;t save a file:</strong> previews, page thumbnails, browsing in the Explorer, and compiling or saving in the LaTeX editor.</li></ul><h2 id="reading-the-list" tabindex="-1">Reading the list <a class="header-anchor" href="#reading-the-list" aria-label="Permalink to &quot;Reading the list&quot;">​</a></h2><p>The newest runs come first, grouped under <strong>Today</strong>, <strong>Yesterday</strong> or the date. Forty entries load at a time; click <strong>Show older</strong> at the end for more.</p><p>Each entry shows:</p><ul><li>a dot, red for a failed run, then the tool&#39;s name, the time and how long the run took;</li><li>for a failed run, the error message;</li><li>the files it made, up to three (click <strong>and <em>N</em> more</strong> to see the rest), with their sizes;</li><li>&quot;from&quot; and the names of the files it started from. Hover over that line to see their full paths.</li></ul><p>Click a file&#39;s name to open it in its usual app, or the folder icon next to it (<strong>Show in folder</strong>) to open File Explorer with the file selected. A file that has been moved or deleted since is greyed out and marked &quot;moved or deleted&quot;.</p><h2 id="searching" tabindex="-1">Searching <a class="header-anchor" href="#searching" aria-label="Permalink to &quot;Searching&quot;">​</a></h2><p>Type in <strong>Search tools and file names</strong> at the top. The list shows the runs whose tool name, or any input or output path, contains what you typed. Because the whole path is searched, a folder name finds everything made in or from that folder. Capital letters don&#39;t matter, except for accented ones.</p><h2 id="removing-entries" tabindex="-1">Removing entries <a class="header-anchor" href="#removing-entries" aria-label="Permalink to &quot;Removing entries&quot;">​</a></h2><ul><li>To remove one entry, click × (<strong>Remove from history</strong>) on it.</li><li>To remove everything, click <strong>Clear history…</strong> at the bottom of the panel, then <strong>Clear</strong>. The button is hidden while you&#39;re searching.</li></ul><p>Both remove only the records. Your files stay where they are.</p><h2 id="turning-the-history-off" tabindex="-1">Turning the history off <a class="header-anchor" href="#turning-the-history-off" aria-label="Permalink to &quot;Turning the history off&quot;">​</a></h2><p>Untick <strong>Keep history</strong> at the top of the panel. Tilepress stops recording new runs, and the panel says &quot;History is off: new runs aren&#39;t recorded.&quot; The entries you already have stay until you remove them. Tick the box again to resume.</p><p>History is on when you first install Tilepress. The choice is saved with your other settings.</p><h2 id="limits-and-storage" tabindex="-1">Limits and storage <a class="header-anchor" href="#limits-and-storage" aria-label="Permalink to &quot;Limits and storage&quot;">​</a></h2><ul><li>The newest 5,000 runs are kept. Older ones are removed as new ones arrive.</li><li>The history is a database file, <code>%LOCALAPPDATA%\\Tilepress\\history.db</code>. While Tilepress runs, two helper files sit next to it, <code>history.db-wal</code> and <code>history.db-shm</code>.</li><li>Two copies of Tilepress can be open at the same time and both record into the same history.</li><li>A problem with the history never stops a tool. If the database can&#39;t be written, the tool still saves its file, and recording stops until you restart Tilepress.</li><li>Uninstalling Tilepress keeps the history. To get rid of it, clear it first, or delete the three <code>history.db</code> files while Tilepress is closed.</li></ul><p>See <a href="/tilepress/docs/privacy">Privacy</a> for everything else Tilepress keeps on your PC.</p>',28)])])}const u=t(a,[["render",n]]);export{f as __pageData,u as default};
